-- RRC109: ten existing output IDs only. Fresh dedicated strict MariaDB session.
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE own_transaction BOOLEAN DEFAULT FALSE;
 DECLARE recipes_before BIGINT DEFAULT 0;
 DECLARE entries_before BIGINT DEFAULT 0;
 DECLARE locked_rows BIGINT DEFAULT 0;
 DECLARE changed_rows BIGINT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
  IF own_transaction THEN ROLLBACK; END IF;
  RESIGNAL;
 END;
 IF @@in_transaction<>0 OR DATABASE()<>'peq_housing_test' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 target/transaction mismatch'; END IF;
 IF FIND_IN_SET('STRICT_ALL_TABLES',@@SESSION.sql_mode)=0 AND FIND_IN_SET('STRICT_TRANS_TABLES',@@SESSION.sql_mode)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 strict mode required'; END IF;
 IF(SELECT COUNT(*)FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME IN('tradeskill_recipe','tradeskill_recipe_entries','items')AND ENGINE='InnoDB')<>3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 InnoDB mismatch'; END IF;
 CREATE TEMPORARY TABLE rrc109_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc109_before LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc109_after LIKE tradeskill_recipe_entries;
 START TRANSACTION;
 SET own_transaction=TRUE;
 SELECT COUNT(*)INTO recipes_before FROM tradeskill_recipe;
 SELECT COUNT(*)INTO entries_before FROM tradeskill_recipe_entries;
 SELECT COUNT(*)INTO locked_rows FROM tradeskill_recipe r JOIN rrc109_recipes e ON r.id=e.id FOR UPDATE;
 IF locked_rows<>11 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 definition/peer missing'; END IF;
 SELECT COUNT(*)INTO locked_rows FROM tradeskill_recipe_entries r JOIN rrc109_before e ON r.id=e.id FOR UPDATE;
 IF locked_rows<>110 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 target/peer entries missing'; END IF;
 IF EXISTS(SELECT 1 FROM rrc109_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 definition/peer drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc109_before e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR(SELECT COUNT(*)FROM tradeskill_recipe_entries r JOIN rrc109_recipes p ON p.id=r.recipe_id)<>110 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 preimage mismatch'; END IF;
 IF(SELECT COUNT(*)FROM items WHERE (`id` <=> 8050 AND BINARY Name=BINARY CONVERT(0x4c617267652047726f6f7665204e6f636b73 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 17 AND `damage` <=> 0 AND `range` <=> 0 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 20 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 65535 AND `races` <=> 65535 AND `slots` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0) OR (`id` <=> 8051 AND BINARY Name=BINARY CONVERT(0x4d656469756d2047726f6f7665204e6f636b73 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 17 AND `damage` <=> 0 AND `range` <=> 0 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 20 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 65535 AND `races` <=> 65535 AND `slots` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0) OR (`id` <=> 8052 AND BINARY Name=BINARY CONVERT(0x536d616c6c2047726f6f7665204e6f636b73 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 17 AND `damage` <=> 0 AND `range` <=> 0 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 20 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 65535 AND `races` <=> 65535 AND `slots` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0) OR (`id` <=> 62477 AND BINARY Name=BINARY CONVERT(0x434c415353203620576f6f6420446973636f726420546970204172726f77 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 27 AND `damage` <=> 7 AND `range` <=> 100 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 100 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 285 AND `races` <=> 65535 AND `slots` <=> 4194304 AND `reqlevel` <=> 0 AND `reclevel` <=> 0) OR (`id` <=> 62478 AND BINARY Name=BINARY CONVERT(0x434c415353203620576f6f6420446973636f726420546970204172726f77 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 27 AND `damage` <=> 7 AND `range` <=> 75 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 100 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 285 AND `races` <=> 65535 AND `slots` <=> 4194304 AND `reqlevel` <=> 0 AND `reclevel` <=> 0) OR (`id` <=> 63899 AND BINARY Name=BINARY CONVERT(0x434c415353203420426f6e6520536572726174656420546970204172726f77 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 27 AND `damage` <=> 6 AND `range` <=> 50 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 100 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 285 AND `races` <=> 65535 AND `slots` <=> 4194304 AND `reqlevel` <=> 0 AND `reclevel` <=> 0) OR (`id` <=> 63900 AND BINARY Name=BINARY CONVERT(0x434c415353203420426f6e6520536572726174656420546970204172726f77 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 27 AND `damage` <=> 6 AND `range` <=> 25 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 100 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 285 AND `races` <=> 65535 AND `slots` <=> 4194304 AND `reqlevel` <=> 0 AND `reclevel` <=> 0) OR (`id` <=> 63901 AND BINARY Name=BINARY CONVERT(0x434c415353203420426f6e6520536572726174656420546970204172726f77 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 27 AND `damage` <=> 6 AND `range` <=> 75 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 100 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 285 AND `races` <=> 65535 AND `slots` <=> 4194304 AND `reqlevel` <=> 0 AND `reclevel` <=> 0) OR (`id` <=> 63923 AND BINARY Name=BINARY CONVERT(0x434c415353203620426f6e6520536572726174656420546970204172726f77 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 27 AND `damage` <=> 7 AND `range` <=> 75 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 100 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 285 AND `races` <=> 65535 AND `slots` <=> 4194304 AND `reqlevel` <=> 0 AND `reclevel` <=> 0) OR (`id` <=> 63924 AND BINARY Name=BINARY CONVERT(0x434c415353203620426f6e6520536572726174656420546970204172726f77 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 27 AND `damage` <=> 7 AND `range` <=> 50 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 100 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 285 AND `races` <=> 65535 AND `slots` <=> 4194304 AND `reqlevel` <=> 0 AND `reclevel` <=> 0) OR (`id` <=> 63936 AND BINARY Name=BINARY CONVERT(0x434c415353203120426f6e6520446973636f726420546970204172726f77 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 27 AND `damage` <=> 6 AND `range` <=> 100 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 100 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 285 AND `races` <=> 65535 AND `slots` <=> 4194304 AND `reqlevel` <=> 0 AND `reclevel` <=> 0) OR (`id` <=> 63937 AND BINARY Name=BINARY CONVERT(0x434c415353203120426f6e6520446973636f726420546970204172726f77 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 27 AND `damage` <=> 6 AND `range` <=> 75 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 100 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 285 AND `races` <=> 65535 AND `slots` <=> 4194304 AND `reqlevel` <=> 0 AND `reclevel` <=> 0) OR (`id` <=> 63995 AND BINARY Name=BINARY CONVERT(0x434c415353203620426f6e6520446973636f726420546970204172726f77 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 27 AND `damage` <=> 8 AND `range` <=> 75 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 100 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 285 AND `races` <=> 65535 AND `slots` <=> 4194304 AND `reqlevel` <=> 0 AND `reclevel` <=> 0) OR (`id` <=> 63996 AND BINARY Name=BINARY CONVERT(0x434c415353203620426f6e6520446973636f726420546970204172726f77 USING utf8mb4) AND `itemclass` <=> 0 AND `itemtype` <=> 27 AND `damage` <=> 8 AND `range` <=> 50 AND `size` <=> 1 AND `stackable` <=> 1 AND `stacksize` <=> 100 AND `nodrop` <=> 1 AND `norent` <=> 1 AND `classes` <=> 285 AND `races` <=> 65535 AND `slots` <=> 4194304 AND `reqlevel` <=> 0 AND `reclevel` <=> 0))<>14 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 native item identity/range drift'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries e WHERE e.iscontainer=0 AND e.successcount>e.componentcount AND e.item_id IN(62477,62478,63899,63900,63901,63923,63924,63936,63937,63995,63996)AND NOT EXISTS(SELECT 1 FROM rrc109_recipes p WHERE p.id=e.recipe_id)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 output-producer universe drift'; END IF;
 UPDATE tradeskill_recipe_entries r JOIN rrc109_after e ON r.id=e.id SET r.item_id=e.item_id WHERE r.id IN(65178,65188,67148,67168,68258,68268,68348,68358,68818,68828);
 SET changed_rows=ROW_COUNT();
 IF changed_rows<>10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 changed-row mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc109_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 definition/peer drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc109_after e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR(SELECT COUNT(*)FROM tradeskill_recipe_entries r JOIN rrc109_recipes p ON p.id=r.recipe_id)<>110 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 postimage mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries e WHERE e.iscontainer=0 AND e.successcount>e.componentcount AND e.item_id IN(62477,62478,63899,63900,63901,63923,63924,63936,63937,63995,63996)AND NOT EXISTS(SELECT 1 FROM rrc109_recipes p WHERE p.id=e.recipe_id)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 output-producer universe drift'; END IF;
 IF(SELECT COUNT(*)FROM tradeskill_recipe)<>recipes_before OR(SELECT COUNT(*)FROM tradeskill_recipe_entries)<>entries_before THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC109 global row-count drift'; END IF;
 DROP TEMPORARY TABLE rrc109_before;
 DROP TEMPORARY TABLE rrc109_after;
 DROP TEMPORARY TABLE rrc109_recipes;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC109',changed_rows,recipes_before,(SELECT COUNT(*)FROM tradeskill_recipe),entries_before,(SELECT COUNT(*)FROM tradeskill_recipe_entries),@@in_transaction;
END//
DELIMITER ;
